"""Reproducible scorecards; keep retained R, fresh OHLC and tick evidence separate."""
import csv,gzip,hashlib,json
from datetime import datetime
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/research/personal-edge-20261127'
def load(p):return json.loads(p.read_text())
def write(p,x):p.write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def n(x):return '—' if x is None else f'{x:.2f}'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(v) for v in row)+' |' for row in rows])

def main():
    ledger=load(ROOT/'src/data/saved-ledger-trades.json');old=load(ROOT/'docs/research/edge-evidence-20261127/scorecard.json')
    rows=[]
    for source in old['configurations']:
        row=dict(source);ts=[t for t in ledger['trades'] if t['strategy_id']==row['strategy_id']]
        wins=[t['realized_r'] for t in ts if t['realized_r']>0];losses=[t['realized_r'] for t in ts if t['realized_r']<0]
        days=sum((datetime.fromisoformat(c['end_exclusive'])-datetime.fromisoformat(c['start'])).total_seconds()/86400 for c in row['coverage'])
        row.update(average_win_r=sum(wins)/len(wins) if wins else None,average_loss_r=sum(losses)/len(losses) if losses else None,covered_calendar_days=days,decisions_per_covered_calendar_day=len(ts)/days,active_entry_days=len({t['entry_time'][:10] for t in ts}),individual_order_count=None)
        rows.append(row)
    write(OUT/'existing-16-detailed.json',dict(schema='retained-ledger-detailed/v1',ledger_sha256=hashlib.sha256((ROOT/'src/data/saved-ledger-trades.json').read_bytes()).hexdigest(),costs=ledger['costs'],rows=rows,limitations=['R units, not dollar or percentage account returns. Unequal coverage; portfolio admission and correlation exist.','Covered calendar days include weekends; active entry days are different. Orders/deals are not retained.','Complete-month positive R is not a profitable-month probability or subscription-adjusted return.']))
    cols=['strategy_id','decisions','net_r','win_rate_pct','average_win_r','average_loss_r','profit_factor','expectancy_r','average_holding_minutes','decisions_per_covered_calendar_day','covered_calendar_days']
    with (OUT/'existing-16-detailed.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows({k:r[k] for k in cols} for r in rows)
    lines=['# HashiBot Personal strategy evidence — 27 November 2026','','The catalogue remains 16 existing configurations plus five Gold Turbo strategies. The additional compression prototype is outside the catalogue. No paid/live execution or Prop policy was enabled.','','## Existing 16: retained costed trades','','These 1,159 records were reused, not regenerated. Results are net R from unequal historical windows, not fresh account backtests. Orders and deals cannot be reconstructed from these records. Full covered months, gaps, dates and chronological halves are retained in `existing-16-detailed.json`.','',''+table(['Configuration','Decisions','Net R','Win %','Avg win R','Avg loss R','PF','Hold min','Decisions/covered day'],[[r['strategy_id'],r['decisions'],n(r['net_r']),n(r['win_rate_pct']),n(r['average_win_r']),n(r['average_loss_r']),n(r['profit_factor']),n(r['average_holding_minutes']),n(r['decisions_per_covered_calendar_day'])] for r in rows]),'','## Fresh Crypto: 1–26 November, 26 calendar days','','Ten existing launch assets, native 4h/1h/15m/5m candle sources as required, paid funding and current volume filters. Six frozen production entry families, two combinations and one frozen prototype. 576 capital/risk/leverage/cost scenarios. Base commissions 5 bps per side, slippage 3 bps per side (ETH complementary 7.5); stress slippage 10 bps (ETH complementary 15). This is an OHLC execution screen, not real bid/ask or exchange qualification. Stops take priority within ambiguous bars. Next-bar entry; gap losses and approximate liquidation checks included.','','The table uses $500, 10× available leverage and 1% fixed decision risk. Leverage changes available margin, not the profit of an unchanged position. Risk headroom reserves the full original decision risk until closure, including after partial exits; this is conservative. Daily/peak limits are experimental 15%/60%, correlated risk 10%, entry margin 50%. These are not customer defaults. Drawdown is sampled equity, not verified intrabar maximum.','',''+table(['Lineup','Return %','Stress %','DD %','Decisions/day','Win %','Avg win $','Avg loss $','Hold min'],[[r['lineup'],n(r['return_pct']),n(next(q['return_pct'] for q in load(OUT/'fresh-crypto-summary.json')['results'] if q['lineup']==r['lineup'] and q['capital']==500 and q['risk_pct']==1 and q['leverage']==10 and q['stress'])),n(r['close_sampled_drawdown_pct']),f"{r['closed_decisions']}/26 = {r['closed_decisions']/26:.2f}",n(r['win_rate_pct']),n(r['average_win_money']),n(r['average_loss_money']),n(r['average_hold_minutes'])] for r in load(OUT/'fresh-crypto-summary.json')['results'] if r['capital']==500 and r['risk_pct']==1 and r['leverage']==10 and not r['stress']]),'','### Crypto combined sizing comparison','','All rows use the same six-family arbitration, prices, costs and 15%/60% limits; sizing changes portfolio admission and realized paths. No risk level was tuned for a guaranteed result.','',''+table(['Capital','Risk %','Leverage','Return %','Stress %','Sampled DD %','Decisions','After $100 fee $'],[[r['capital'],r['risk_pct'],r['leverage'],n(r['return_pct']),n(next(q['return_pct'] for q in load(OUT/'fresh-crypto-summary.json')['results'] if q['lineup']==r['lineup'] and q['capital']==r['capital'] and q['risk_pct']==r['risk_pct'] and q['leverage']==r['leverage'] and q['stress'])),n(r['close_sampled_drawdown_pct']),r['closed_decisions'],n(r['net_after_full_100_subscription'])] for r in load(OUT/'fresh-crypto-summary.json')['results'] if r['lineup']=='ADAPTIVE_EXISTING_SIX' and r['capital'] in (100,500,1000,25000) and not r['stress']]),'','A full $100 subscription is an external cost sensitivity; it was not withdrawn from collateral. Terminal positions are forcibly marked/closed at the period end; open-before-terminal counts and exit reasons are disclosed in the JSON. One partial November cannot establish median monthly returns, profitable-month probability or sustainable growth. The ETH complementary case uses perpetual data, unlike its older spot-reference ledger. The losing compression prototype remains rejected.','','## Existing Gold Standard: October ticks, higher Personal sizing','','These three unchanged rules are intraday/swing, not the new Turbo scalpers. Separate accounts at each size; returns must not be added. Actual retained bid/ask ticks, 100 oz/lot, 0.01 minimum/step, 100× leverage, $3.50/lot/side commission. Base slippage $0.02/side and 200 ms execution; stress $0.05 and 500 ms. Same 15% daily/60% peak/50% entry margin experimental constraints across risk levels. Overnight financing is unverified and omitted; profits are before financing and subscription. Full 96 cases and receipts are retained.','',''+table(['Configuration','Capital','Risk %','Return %','Stress %','DD %','Decisions','Avg win $','Avg loss $'],[[r['arm']['strategy_id'],r['arm']['capital'],r['arm']['risk'],n(r['returnPct']),n(next(q['returnPct'] for q in load(OUT/'personal-gold-summary.json')['result']['results'] if q['arm']['strategy_id']==r['arm']['strategy_id'] and q['arm']['capital']==r['arm']['capital'] and q['arm']['risk']==r['arm']['risk'] and q['arm']['stress'])),n(r['drawdownPct']),r['closedTrades'],n(r['average_win_money']),n(r['average_loss_money'])] for r in load(OUT/'personal-gold-summary.json')['result']['results'] if r['arm']['capital'] in (500,25000) and not r['arm']['stress']]),'']
    turbo=[]
    for risk in (1,3,5):
        p=ROOT/f'.tmp/personal-turbo-corrected-{risk}.json'
        if not p.exists():continue
        d=load(p)
        for r in d['results']:
            b=d['closed_baskets'][f"{r['lineup']}:{r['capital']:g}"]
            wins=[v['net'] for v in b if v['net']>0];losses=[v['net'] for v in b if v['net']<0]
            if abs(sum(v['net'] for v in b)-r['final_equity']+r['capital'])>1e-5:raise ValueError('TURBO_CASH_AUDIT')
            r.update(risk_pct=risk,average_win_money=sum(wins)/len(wins) if wins else None,average_loss_money=sum(losses)/len(losses) if losses else None)
            turbo.append(r)
        (OUT/f'turbo-corrected-{risk}-receipts.json.gz').write_bytes(gzip.compress(p.read_bytes(),mtime=0))
    if len(turbo)==72:
        write(OUT/'turbo-corrected-summary.json',dict(schema='turbo-personal-corrected/v1',results=turbo,scope='22 October weekdays, 08–16 UTC only; observed nonempty native quote bars. Selected sessions, not continuous full month.'))
        lines+=['## All five Turbo scalpers: corrected local runtime','','22 October weekdays, 08–16 UTC only; 2,643,309 original quotes. The margin correction includes existing account margin, uncertain pending reservations and margin-constrained volume reduction. All five retain their scalping horizons. Fixed 0.2% basket equity target; 20% session profit lock, 5% session trailing; 15% daily, 60% peak experimental loss allowances; 50% entry margin cap. The target and margin limits mean increasing configured risk need not increase permitted volume or returns. No parameter sweep or entry retuning. These are historical fake-terminal execution replays, not native broker certification.','',''+table(['Lineup','Capital','Risk %','Return %','DD %','Baskets/day','Entry orders','Win %','Avg win $','Avg loss $','Hold min'],[[r['lineup'],r['capital'],r['risk_pct'],n(r['net_return_pct']),n(r['maximum_drawdown_pct']),f"{r['independent_baskets']}/22 = {r['baskets_per_selected_session']:.2f}",r['individual_orders'],n(r['win_rate_pct']),n(r['average_win_money']),n(r['average_loss_money']),n(r['average_holding_minutes'])] for r in turbo if r['capital'] in (500,25000)]),'','The apparent independent unit is a coordinated basket, not each order. No stressed second Turbo replay is claimed here. Quotes outside the selected sessions were not traded. Full reasons, source hashes, fills, realized basket cash and cases are retained in compressed receipts.']
    else:lines+=['## Gold Turbo corrected replay','','Corrected 72-case replay is still running; no earlier over-margin rejection results are represented as final corrected results.']
    lines+=['','## What this evidence supports','','Crypto trend pullback and the six-family combination are candidates for forward demo comparison; the combination improves participation in this November window, with substantial sampled drawdowns. ETH complementary is slower and does not satisfy a scalp offering. DOGE has only two decisions; LTC and the new compression prototype do not justify promotion. Gold Standard momentum/band rules merit demo comparison only where minimum executable volume fits; higher risk increases severe-loss exposure.','','All five Turbo implementations remain available for development/demo qualification. A profitable arm or profitable aggregate does not validate every component. Do not promote losing components, increase risk to repair their entries, or advertise 20% sessions / monthly doubling. Fresh FX entry validation and multiple unseen chronological periods remain outstanding.','','## Exact engineering improvements and remaining qualification','','Implemented: closed-candle structure cache with per-tick developing-event reassessment; original-feature equality tested. Aggregate account and uncertain pending margin now consume the shared margin budget; lot size reduces to executable headroom and never rounds up beyond risk. Negative free margin is normalized only for protective management facts, while new entries still fail sizing. Research variants require the fake replay terminal, preserving production authorization and conservative defaults.','','Functionally tested: 156 targeted Gold Turbo tests, nine Crypto accounting/execution invariant tests; 576 Crypto and 96 Gold Standard account cash audits. Corrected Turbo accounts audit once their full replay completes. No broad repository test suite or live broker session was run.','','Historically evaluated: retained 16-family ledger; fresh November six-family Crypto OHLC screen; October three-family Gold Standard tick screen; corrected Turbo selected-session replay when receipts above exist. Profitability validated / commercially qualified: not established. Demo activation still requires native MT5 compilation, broker demo integration and recovery/partial-fill checks; venue-specific Crypto order handling; confirmed subscriptions, provider secrets and Telegram setup. No live or paid activation.','','Reproduce: restore the source archive, prepare Crypto input, bundle/run `crypto_validation_signals.ts`, then run `crypto_personal_screen.py`. Scripts retain exact source hashes and period boundaries. Gold uses the previously preserved October tick archive; no duplicate download. Read `experiment.json`, `data-index.json`, `crypto-source-data.json`, summaries and compressed receipts for all case settings.']
    (OUT/'RESULTS.md').write_text('\n'.join(lines)+'\n')
    print('Reported',len(rows),'existing configurations;',len(turbo),'corrected Turbo accounts')

if __name__=='__main__':main()
